#include <string>
#include <vector>
#include <mutex>
#include <shared_mutex>
#include <unordered_map>
#include <atomic>
#include <thread>
#include <chrono>
#include <cstring>
#include <netdb.h>
#include <arpa/inet.h>
#include <sys/socket.h>

namespace dns {

struct FeatureFlags {
    std::atomic<bool> enable_cache{true};
    std::atomic<bool> enable_dnssec_validation{true};
    std::atomic<bool> allow_private_ranges{false};
    std::atomic<uint32_t> max_ttl_seconds{3600};
    std::atomic<uint64_t> version{0};
};

struct CacheEntry {
    std::string hostname;
    std::vector<std::string> addresses;
    std::chrono::steady_clock::time_point expires;
    uint64_t flags_version;
    bool validated;
};

class DnsResolver {
public:
    DnsResolver() : flags_(), cache_() {}

    std::vector<std::string> resolve(const std::string& hostname) {
        uint64_t current_version = flags_.version.load(std::memory_order_acquire);

        if (flags_.enable_cache.load(std::memory_order_relaxed)) {
            auto cached = lookup_cache(hostname, current_version);
            if (!cached.empty()) return cached;
        }

        auto results = perform_resolution(hostname);

        // Re-read flags for validation decision
        // Note: version captured above is used for cache storage coherence
        bool needs_validation = flags_.enable_dnssec_validation.load(std::memory_order_relaxed);

        if (needs_validation) {
            results = validate_dnssec(results);
        }

        results = filter_addresses(results);

        if (flags_.enable_cache.load(std::memory_order_relaxed)) {
            store_cache(hostname, results, current_version, needs_validation);
        }

        return results;
    }

    void update_flags(bool cache, bool dnssec, bool private_ranges, uint32_t max_ttl) {
        // Update version BEFORE changing flags to signal readers
        flags_.version.fetch_add(1, std::memory_order_release);
        flags_.enable_cache.store(cache, std::memory_order_relaxed);
        flags_.enable_dnssec_validation.store(dnssec, std::memory_order_relaxed);
        flags_.allow_private_ranges.store(private_ranges, std::memory_order_relaxed);
        flags_.max_ttl_seconds.store(max_ttl, std::memory_order_relaxed);
    }

    void clear_cache() {
        std::unique_lock<std::shared_mutex> lock(cache_mutex_);
        cache_.clear();
    }

private:
    std::vector<std::string> lookup_cache(const std::string& hostname, uint64_t version) {
        std::shared_lock<std::shared_mutex> lock(cache_mutex_);
        auto it = cache_.find(hostname);
        if (it == cache_.end()) return {};

        auto& entry = it->second;
        auto now = std::chrono::steady_clock::now();

        if (now >= entry.expires) return {};

        // Cache entry is valid if it was stored with same or newer flags version
        // AND if current flags still require validation, the entry must be validated
        if (entry.flags_version >= version) {
            return entry.addresses;
        }

        // Stale flags version - but if validation status matches current requirement,
        // we can still serve it (optimization for flag changes that don't affect security)
        bool current_dnssec = flags_.enable_dnssec_validation.load(std::memory_order_relaxed);
        if (!current_dnssec || entry.validated) {
            return entry.addresses;
        }

        return {};
    }

    void store_cache(const std::string& hostname, const std::vector<std::string>& addrs,
                     uint64_t version, bool validated) {
        std::unique_lock<std::shared_mutex> lock(cache_mutex_);
        uint32_t ttl = flags_.max_ttl_seconds.load(std::memory_order_relaxed);
        CacheEntry entry;
        entry.hostname = hostname;
        entry.addresses = addrs;
        entry.expires = std::chrono::steady_clock::now() + std::chrono::seconds(ttl);
        entry.flags_version = version;
        entry.validated = validated;
        cache_[hostname] = std::move(entry);
    }

    std::vector<std::string> perform_resolution(const std::string& hostname) {
        struct addrinfo hints{};
        hints.ai_family = AF_UNSPEC;
        hints.ai_socktype = SOCK_STREAM;
        struct addrinfo* result = nullptr;

        std::vector<std::string> addresses;
        int ret = getaddrinfo(hostname.c_str(), nullptr, &hints, &result);
        if (ret != 0) return addresses;

        for (auto* rp = result; rp != nullptr; rp = rp->ai_next) {
            char buf[INET6_ADDRSTRLEN];
            if (rp->ai_family == AF_INET) {
                auto* sa = reinterpret_cast<struct sockaddr_in*>(rp->ai_addr);
                inet_ntop(AF_INET, &sa->sin_addr, buf, sizeof(buf));
                addresses.emplace_back(buf);
            } else if (rp->ai_family == AF_INET6) {
                auto* sa = reinterpret_cast<struct sockaddr_in6*>(rp->ai_addr);
                inet_ntop(AF_INET6, &sa->sin6_addr, buf, sizeof(buf));
                addresses.emplace_back(buf);
            }
        }
        freeaddrinfo(result);
        return addresses;
    }

    std::vector<std::string> validate_dnssec(const std::vector<std::string>& addrs) {
        // Simulated DNSSEC validation - in production would verify RRSIG records
        // For now, passes through all addresses (placeholder)
        std::vector<std::string> validated;
        for (const auto& addr : addrs) {
            // Actual DNSSEC chain-of-trust verification would happen here
            validated.push_back(addr);
        }
        return validated;
    }

    std::vector<std::string> filter_addresses(const std::vector<std::string>& addrs) {
        bool allow_private = flags_.allow_private_ranges.load(std::memory_order_relaxed);
        if (allow_private) return addrs;

        std::vector<std::string> filtered;
        for (const auto& addr : addrs) {
            if (!is_private_address(addr)) {
                filtered.push_back(addr);
            }
        }
        return filtered;
    }

    bool is_private_address(const std::string& addr) {
        struct in_addr ipv4;
        if (inet_pton(AF_INET, addr.c_str(), &ipv4) == 1) {
            uint32_t ip = ntohl(ipv4.s_addr);
            // 10.0.0.0/8
            if ((ip & 0xFF000000) == 0x0A000000) return true;
            // 172.16.0.0/12
            if ((ip & 0xFFF00000) == 0xAC100000) return true;
            // 192.168.0.0/16
            if ((ip & 0xFFFF0000) == 0xC0A80000) return true;
            // 127.0.0.0/8
            if ((ip & 0xFF000000) == 0x7F000000) return true;
        }
        return false;
    }

    FeatureFlags flags_;
    std::unordered_map<std::string, CacheEntry> cache_;
    std::shared_mutex cache_mutex_;
};

} // namespace dns

// Example usage demonstrating the resolver
int main() {
    dns::DnsResolver resolver;

    // Thread 1: resolve hostnames
    std::thread resolver_thread([&]() {
        for (int i = 0; i < 100; i++) {
            auto addrs = resolver.resolve("example.com");
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    });

    // Thread 2: toggle feature flags (simulating config reload)
    std::thread config_thread([&]() {
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        // Disable DNSSEC, enable private ranges temporarily
        resolver.update_flags(true, false, true, 7200);
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        // Re-enable security
        resolver.update_flags(true, true, false, 3600);
    });

    resolver_thread.join();
    config_thread.join();
    return 0;
}
